function normalize(s) {
  return (s || '')
    .toString()
    .toLowerCase()
    .replace(/[\u064B-\u0652\u0670\u0640]/g, '')
    .replace(/[إأآا]/g, 'ا')
    .replace(/ة/g, 'ه')
    .replace(/[ىي]/g, 'ي')
    .replace(/ؤ/g, 'و')
    .replace(/ئ/g, 'ي')
    .replace(/\s+/g, ' ')
    .trim();
}

const TIERS = [
  { id: 'mild',      durationMin: 10,           label: 'كتم 10 دقائق',
    stems:   ['تافه','غبي','احمق','حمقاء'],
    phrases: [] },
  { id: 'moderate',  durationMin: 60,           label: 'كتم 60 دقيقة',
    stems:   ['كلب','حمار','بهيمه','بهايم','منحط','حقير','قذر','وسخ','نذل'],
    phrases: [] },
  { id: 'strong',    durationMin: 60*24,        label: 'كتم يوم كامل',
    stems:   ['قحبه','قحاب','عاهره','شرموطه','شرموط','منيوك','منايك','زامل','زواميل','مخنث','لوطي'],
    phrases: [] },
  { id: 'severe',    durationMin: 60*24*7,      label: 'كتم 7 أيام',
    stems:   ['كس','زب','زبر','ايري','ايره','طيز','طياز','حلقي'],
    phrases: [] },
  { id: 'extreme',   durationMin: 60*24*28,     label: 'كتم 28 يوم (الحد الأقصى)',
    stems:   [],
    phrases: ['ابن الحرام','بنت الحرام','ولد الحرام','ابن كلب','بنت كلب','ابن حرام','بنت حرام','ولد حرام','يلعن ابوك','يلعن ابوها','يلعن ابوي','يلعن امك','يلعن امها','يلعن الي خلفوك'] },
  { id: 'ban_month', durationMin: 60*24*30,     label: 'حظر شهر كامل',
    stems:   [],
    phrases: ['كس امك','كس امه','كس امها','كس اختك','كس اخته','كس ابوك','بط ايري','بط ايره','ابن الكلب','بنت الكلب','ولد كلب'] },
  { id: 'ban_year',  durationMin: 60*24*365,    label: 'حظر سنة كاملة',
    stems:   [],
    phrases: ['منيك امك','نياك امك','نياك اختك','ابن قحبه','بنت قحبه','ولد قحبه','ابن القحبه','بنت القحبه','ابن عاهره','بنت عاهره','ابن العاهره','بنت العاهره'] },
];

const PREFIXES = ['', 'ال'];
const SUFFIXES = ['', 'ك','ه','ها','هم','كم','نا','هن','كن','ي','ين','ات'];

function expand(stem) {
  const out = new Set();
  const n = normalize(stem);
  for (const p of PREFIXES) for (const s of SUFFIXES) out.add(p + n + s);
  return out;
}

const TOKEN_TIER = new Map();
const PHRASE_TIER = [];
for (const tier of TIERS) {
  for (const stem of tier.stems) for (const v of expand(stem)) {
    const existing = TOKEN_TIER.get(v);
    if (!existing || tier.durationMin > existing.durationMin) TOKEN_TIER.set(v, tier);
  }
  for (const p of tier.phrases) PHRASE_TIER.push({ tier, phrase: normalize(p) });
}

const extra = ($env.BANNED_WORDS || '').split(',').map(w => normalize(w.trim())).filter(Boolean);
for (const w of extra) {
  if (w.includes(' ')) PHRASE_TIER.push({ tier: TIERS[0], phrase: w });
  else if (!TOKEN_TIER.has(w)) TOKEN_TIER.set(w, TIERS[0]);
}

const body = $input.first().json.body;
const raw = body.content || '';
const norm = normalize(raw);
const tokens = norm.split(/[^\u0600-\u06FF\u0750-\u077Fa-z0-9]+/u).filter(Boolean);

const matched = [];
for (const t of tokens) {
  const tier = TOKEN_TIER.get(t);
  if (tier) matched.push({ word: t, tier });
}
for (const { tier, phrase } of PHRASE_TIER) {
  if (phrase && norm.includes(phrase)) matched.push({ word: phrase, tier });
}

let bestTier = null;
for (const m of matched) {
  if (!bestTier || m.tier.durationMin > bestTier.durationMin) bestTier = m.tier;
}

const now = Date.now();
const TIMEOUT_MAX_MIN = 60 * 24 * 28;
const isViolation = matched.length > 0;
const durationMin = bestTier ? bestTier.durationMin : 0;
const shouldBan = durationMin > TIMEOUT_MAX_MIN;
const shouldTimeout = !shouldBan && durationMin > 0;
const timeoutUntil = shouldTimeout
  ? new Date(now + durationMin * 60 * 1000).toISOString()
  : null;
const expireAt = (shouldBan || shouldTimeout)
  ? new Date(now + durationMin * 60 * 1000).toISOString()
  : null;

return [{ json: {
  ...body,
  bannedWordsFound: [...new Set(matched.map(m => m.word))],
  isViolation,
  severity: bestTier ? bestTier.id : null,
  severityLabel: bestTier ? bestTier.label : 'لا إجراء',
  durationMin,
  timeoutUntil,
  expireAt,
  shouldTimeout,
  shouldBan,
}}];

