const data = $getWorkflowStaticData('global');
data.violations = data.violations || {};
const body = $input.first().json;
const userId = body.author.id;
const now = Date.now();
const record = data.violations[userId] || { count: 0, history: [] };
record.count += 1;
record.history = (record.history || []).slice(-9);
record.history.push({
  at: now,
  severity: body.severity,
  durationMin: body.durationMin,
  words: body.bannedWordsFound,
});
record.lastAt = now;
data.violations[userId] = record;
return [{ json: { ...body, violationCount: record.count } }];
